void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.x;

    uv = uv*3.2+vec2(.1,.03)*iTime;

    vec2 res = vec2(3,64);
    fragColor = texelFetch(iChannel0,ivec2(fract((floor(uv*res)+.5)/res)*iChannelResolution[0].xy),0);

    if ( fract(uv.y*2.) < 1./16. )
    {
        res = vec2(25,5);
        fragColor = texelFetch(iChannel0,ivec2(fract((floor(.5+uv*res)+.5)/res)*iChannelResolution[0].xy),0);
    }

    fragColor = fragColor.gbra;

    float shades = 4.;
    fragColor.rg = dot(fragColor.rg,vec2(.5)) + vec2(1,-1)*(-.5+floor( shades*(fragColor.r-fragColor.g)+.5 ))/shades;

    vec4 res4 = vec4(5);
    fragColor = (floor(fragColor*res4)+.5)/res4;
    fragColor.a = 1.;
}
